import argparse
import json
from pathlib import Path
import sys
import tempfile
from . import ContactFlow

ACTIONS = {'add': 'add_contact', 'update-contact': 'update_contact', 'update-contacts': 'update_contacts', 'rename-contacts': 'rename_contacts', 'follow-up': 'follow_up', 'find': 'find', 'search-contacts': 'search_contacts', 'duplicate-candidates': 'duplicate_candidates', 'timeline': 'timeline', 'merge': 'merge_contacts', 'merge-batch': 'batch_merge_contacts','set-tags': 'set_tags', 'get-tags': 'get_tags', 'rename-tags': 'rename_tags', 'import-contacts': 'import_contacts', 'preview-contact-import': 'preview_contact_import', 'import-contact-tags': 'import_contact_tags', 'import-followups': 'import_followups', 'import-opportunities': 'import_opportunities', 'add-opportunity': 'add_opportunity', 'set-stage': 'set_stage', 'set-stages': 'set_stages', 'reopen-opportunities': 'reopen_opportunities', 'stage-history': 'stage_history', 'correct-stage-dates': 'correct_stage_dates', 'stage-change-report': 'stage_change_report', 'win-cycle-report': 'win_cycle_report', 'conversion-report': 'conversion_report', 'qualified-duration-report': 'qualified_duration_report', 'qualified-duration-summary': 'qualified_duration_summary', 'find-opportunities': 'find_opportunities', 'transfer-opportunities': 'transfer_opportunities', 'funnel-report': 'funnel_report', 'funnel-snapshot-report': 'funnel_snapshot_report', 'set-opportunity-amount': 'set_opportunity_amount', 'set-close-dates': 'set_close_dates', 'opportunity-amount-report': 'opportunity_amount_report', 'forecast-report': 'forecast_report', 'monthly-forecast-report': 'monthly_forecast_report', 'set-reminder': 'set_reminder', 'clear-reminder': 'clear_reminder', 'complete-reminder': 'complete_reminder', 'complete-reminders': 'complete_reminders', 'postpone-reminders': 'postpone_reminders', 'due-reminders': 'due_reminders', 'followup-report': 'followup_report', 'correct-followups': 'correct_followups', 'remove-followups': 'remove_followups', 'inactive-contacts': 'inactive_contacts', 'stalled-opportunities': 'stalled_opportunities'}

def samples(name):
    return json.loads((Path(__file__).resolve().parent.parent / "examples" / name).read_text(encoding="utf-8"))

def demo(app):
    for contact in samples("contacts.json"):
        app.add_contact(**contact)
    for entry in samples("followups.json"):
        app.follow_up(**entry)
    return app.timeline("C-001")

def main(argv=None):
    parser = argparse.ArgumentParser(description="客户跟进工作台")
    parser.add_argument("--root", required=True, help="local data directory")
    parser.add_argument("action", choices=[*ACTIONS, "demo"])
    parser.add_argument("input", nargs="?", help="UTF-8 JSON object, or array of objects, containing API arguments")
    args = parser.parse_args(argv)
    try:
        if args.action == "demo":
            # Sample operations run in a fresh child directory and never overwrite user's data.
            Path(args.root).mkdir(parents=True, exist_ok=True)
            with tempfile.TemporaryDirectory(prefix="sample-", dir=args.root) as location:
                value = demo(ContactFlow(location))
        else:
            payload = json.loads(Path(args.input).read_text(encoding="utf-8")) if args.input else {}
            app = ContactFlow(args.root)
            method = getattr(app, ACTIONS[args.action])
            if isinstance(payload, list):
                value = []
                for row in payload:
                    if not isinstance(row, dict):
                        raise ValueError("each input must be an object")
                    value.append(method(**row))
            elif isinstance(payload, dict):
                value = method(**payload)
            else:
                raise ValueError("input must be an object or array")
        print(json.dumps(value, ensure_ascii=False, sort_keys=True))
        return 0
    except (ValueError, KeyError, TypeError, OSError) as error:
        print(json.dumps({"error": str(error)}, ensure_ascii=False), file=sys.stderr)
        return 2

if __name__ == "__main__":
    raise SystemExit(main())

import csv
import io
import json
import unicodedata
from calendar import monthrange
from datetime import date
from decimal import Decimal, ROUND_HALF_UP
from .storage import JsonStore, text, calendar_day, positive, amount_string, amount_cents, format_cents

CONTACT_FIELDS = ("contact_id", "name", "email", "organization")
FOLLOWUP_FIELDS = ("contact_id", "on", "note")
OPPORTUNITY_FIELDS = ("opportunity_id", "contact_id", "title", "stage")
TAG_IMPORT_FIELDS = ("contact_id", "tag")
UPDATABLE_FIELDS = ("name", "email", "organization")
STAGES = ("new", "qualified", "won", "lost")
STAGE_TRANSITIONS = {"new": ("qualified", "lost"), "qualified": ("won", "lost")}

def forecast_probability(value, label):
    # Probabilities reuse the amount grammar (trimmed nonnegative decimal, at
    # most two fraction digits); keep the percent as hundredths so a weighted
    # amount stays in exact integer arithmetic. Range is inclusive 0..100.
    hundredths = amount_cents(amount_string(value, label))
    if hundredths > 10000:
        raise ValueError(label + " must be between 0 and 100")
    return hundredths

def normalize_tag(value):
    # One tag follows the set-tags rule: trim, casefold, keep inner whitespace.
    if not isinstance(value, str):
        raise ValueError("each tag must be a string")
    tag = value.strip().casefold()
    if not tag:
        raise ValueError("tags must be nonempty strings")
    return tag

def normalize_tags(value):
    if not isinstance(value, list):
        raise ValueError("tags must be a list")
    return sorted({normalize_tag(item) for item in value})

def _scan_json_string(expression, start):
    # A tag is one JSON double-quoted string; operators and parentheses inside
    # the quotes are tag content. The token ends at the first unescaped quote.
    index = start + 1
    while index < len(expression):
        char = expression[index]
        if char == "\\":
            index += 2
        elif char == '"':
            try:
                value = json.loads(expression[start:index + 1])
            except ValueError as error:
                raise ValueError("invalid JSON string in tag expression") from error
            # Decoded tags follow set-tags normalization: trim, casefold, keep
            # inner whitespace and every other character.
            tag = value.strip().casefold()
            if not tag:
                raise ValueError("tags must be nonempty strings")
            return ("tag", tag), index + 1
        else:
            index += 1
    raise ValueError("unterminated string in tag expression")

def _tokenize_tag_expression(expression):
    # Unicode whitespace between tokens is ignored; anything that is not a
    # quoted tag, &&, ||, ! or a parenthesis is an unknown symbol (a bare tag
    # included).
    tokens = []
    index = 0
    while index < len(expression):
        char = expression[index]
        if char.isspace():
            index += 1
        elif char == '"':
            token, index = _scan_json_string(expression, index)
            tokens.append(token)
        elif expression.startswith("&&", index):
            tokens.append("&&")
            index += 2
        elif expression.startswith("||", index):
            tokens.append("||")
            index += 2
        elif char in "!()":
            tokens.append(char)
            index += 1
        else:
            raise ValueError("unexpected character in tag expression: " + char)
    return tokens

def _parse_or(tokens, position):
    left, position = _parse_and(tokens, position)
    while position < len(tokens) and tokens[position] == "||":
        right, position = _parse_and(tokens, position + 1)
        left = _both_or(left, right)
    return left, position

def _both_or(left, right):
    return lambda tags: left(tags) or right(tags)

def _parse_and(tokens, position):
    left, position = _parse_unary(tokens, position)
    while position < len(tokens) and tokens[position] == "&&":
        right, position = _parse_unary(tokens, position + 1)
        left = _both_and(left, right)
    return left, position

def _both_and(left, right):
    return lambda tags: left(tags) and right(tags)

def _parse_unary(tokens, position):
    # Negation binds tightest and stacks: !!“a” is “a”.
    if position < len(tokens) and tokens[position] == "!":
        inner, position = _parse_unary(tokens, position + 1)
        return (lambda tags, inner=inner: not inner(tags)), position
    return _parse_primary(tokens, position)

def _parse_primary(tokens, position):
    if position >= len(tokens):
        raise ValueError("missing operand in tag expression")
    token = tokens[position]
    if isinstance(token, tuple):
        tag = token[1]
        return (lambda tags, tag=tag: tag in tags), position + 1
    if token == "(":
        inner, position = _parse_or(tokens, position + 1)
        if position >= len(tokens) or tokens[position] != ")":
            raise ValueError("unbalanced parentheses in tag expression")
        return inner, position + 1
    # An operator or ")" where an operand belongs: missing operand (this also
    # covers empty parentheses).
    raise ValueError("missing operand in tag expression")

def _tag_expression_predicate(expression):
    # The whole expression tokenizes and parses up front, so a malformed tail
    # rejects even when the store is empty or earlier conditions already decide.
    if not isinstance(expression, str) or not expression.strip():
        raise ValueError("tag_expression must be a nonempty string")
    tokens = _tokenize_tag_expression(expression)
    predicate, position = _parse_or(tokens, 0)
    if position != len(tokens):
        # Adjacent tags with no operator, a stray ")" or any other trailing
        # content after a complete expression.
        raise ValueError("unexpected content after complete tag expression")
    return predicate

# Distinguishes an omitted next_reminder (auto-renew a monthly reminder) from
# an explicit None (terminate repetition and clear the reminder).
_UNSET = object()

def _is_repeating(reminder):
    # Reminders saved before monthly repetition existed lack both fields and
    # read as one-time reminders.
    return reminder.get("repeat_monthly") is True and type(reminder.get("anchor_day")) is int

def _next_monthly_due(due_on, anchor_day, on):
    # Candidates run from the month after the current due date, pinned to the
    # anchor day and clamped to the end of shorter months; the first candidate
    # strictly later than the completion date wins, so completing early never
    # keeps the current month and skipped months stay skipped.
    year, month = int(due_on[:4]), int(due_on[5:7])
    month += 1
    if month > 12:
        year, month = year + 1, 1
    while True:
        if year > 9999:
            raise ValueError("next reminder due_on would exceed 9999-12-31")
        candidate = "%04d-%02d-%02d" % (year, month, min(anchor_day, monthrange(year, month)[1]))
        if candidate > on:
            return candidate
        month += 1
        if month > 12:
            year, month = year + 1, 1

def _renewed_reminder(current, on):
    # Auto-renewal keeps the original note and repetition rule; the completion
    # note only goes into the followup record.
    return {"contact_id": current["contact_id"],
            "due_on": _next_monthly_due(current["due_on"], current["anchor_day"], on),
            "note": current["note"],
            "repeat_monthly": True,
            "anchor_day": current["anchor_day"]}

class ContactFlow(JsonStore):
    def add_contact(self, contact_id, name, email, organization):
        contact_id, name = text(contact_id, "contact_id"), text(name, "name")
        email, organization = text(email, "email").lower(), text(organization, "organization")
        if email.count("@") != 1 or any(c.isspace() for c in email) or not all(email.split("@")):
            raise ValueError("invalid email")
        data = self._read()
        contacts = data.setdefault("contacts", {})
        if contact_id in contacts or any(c["email"] == email for c in contacts.values()):
            raise ValueError("contact id or email already exists")
        contact = {"contact_id": contact_id, "name": name, "email": email, "organization": organization}
        contacts[contact_id] = contact
        self._write(data)
        return contact

    def update_contact(self, contact_id, changes):
        contact_id = text(contact_id, "contact_id")
        normalized = self._normalize_changes(changes)
        data = self._read()
        contacts = data.get("contacts", {})
        contact = contacts.get(contact_id)
        if contact is None:
            raise ValueError("unknown contact")
        new_email = normalized.get("email")
        if new_email is not None and new_email != contact["email"] and any(
                other["email"] == new_email for other_id, other in contacts.items() if other_id != contact_id):
            raise ValueError("contact id or email already exists")
        # Everything validates before this point; a fully identical update reports the contact
        # without rewriting the file, so rejected and no-op calls never create the data directory.
        if all(contact[key] == value for key, value in normalized.items()):
            return contact
        contact.update(normalized)
        self._write(data)
        return contact

    @staticmethod
    def _normalize_changes(changes):
        if not isinstance(changes, dict) or not changes:
            raise ValueError("changes must be a nonempty object")
        normalized = {}
        for key, value in changes.items():
            if key not in UPDATABLE_FIELDS:
                raise ValueError("changes contains an unsupported field: " + str(key))
            # None and other non-strings can never clear a field; a trimmed value must stay nonempty.
            clean = text(value, key)
            if key == "email":
                clean = clean.lower()
                if clean.count("@") != 1 or any(c.isspace() for c in clean) or not all(clean.split("@")):
                    raise ValueError("invalid email")
            normalized[key] = clean
        return normalized

    def update_contacts(self, updates):
        # The whole batch validates before any contact changes, so emails can be
        # swapped or cycled within the batch while final duplicates still reject it.
        if not isinstance(updates, list):
            raise ValueError("updates must be a list")
        if not updates:
            # An empty batch succeeds with an empty result and never touches storage.
            return []
        entries = []
        seen = set()
        for item in updates:
            if not isinstance(item, dict) or set(item) != {"contact_id", "changes"}:
                raise ValueError("each update must be an object with exactly contact_id and changes")
            contact_id = text(item["contact_id"], "contact_id")
            if contact_id in seen:
                raise ValueError("duplicate contact id in updates")
            seen.add(contact_id)
            entries.append((contact_id, self._normalize_changes(item["changes"])))
        data = self._read()
        contacts = data.get("contacts", {})
        planned = []
        updated_by_id = {}
        for contact_id, normalized in entries:
            contact = contacts.get(contact_id)
            if contact is None:
                raise ValueError("unknown contact")
            updated = dict(contact)
            updated.update(normalized)
            planned.append((contact, updated))
            updated_by_id[contact_id] = updated
        # Uniqueness is judged on the final whole-store state, including non-participants;
        # members swapping or cycling emails among themselves therefore stays unique.
        final_emails = [updated_by_id[cid]["email"] if cid in updated_by_id else contact["email"]
                        for cid, contact in contacts.items()]
        if len(set(final_emails)) != len(final_emails):
            raise ValueError("contact id or email already exists")
        # Results are the complete contacts in input order, unchanged when the batch is a no-op.
        results = [updated for _, updated in planned]
        if all(contact == updated for contact, updated in planned):
            return results
        for contact, updated in planned:
            contact.update(updated)
        self._write(data)
        return results

    def rename_contacts(self, renames):
        # The whole batch validates against the pre-call identities before any
        # contact, followup, opportunity, tag or reminder changes, so a
        # rejected batch never touches storage; every rename commits in a
        # single write.
        if not isinstance(renames, list):
            raise ValueError("renames must be a list")
        if not renames:
            # An empty batch succeeds with an empty result and never touches storage.
            return []
        entries = []
        old_seen = set()
        new_seen = set()
        for item in renames:
            if not isinstance(item, dict) or set(item) != {"old_id", "new_id"}:
                raise ValueError("each rename must be an object with exactly old_id and new_id")
            old_id = text(item["old_id"], "old_id")
            new_id = text(item["new_id"], "new_id")
            # Normalized ids are case-sensitive; a repeated old or new id (even
            # an identical item) rejects the whole batch.
            if old_id in old_seen:
                raise ValueError("duplicate old id in renames")
            if new_id in new_seen:
                raise ValueError("duplicate new id in renames")
            old_seen.add(old_id)
            new_seen.add(new_id)
            entries.append((old_id, new_id))
        data = self._read()
        contacts = data.get("contacts", {})
        mapping = {}
        for old_id, new_id in entries:
            if old_id not in contacts:
                raise ValueError("unknown contact")
            mapping[old_id] = new_id
        # A new id already taken by a contact outside the batch rejects it all;
        # ids of participants stay free to be swapped or cycled among themselves.
        for _, new_id in entries:
            if new_id in contacts and new_id not in mapping:
                raise ValueError("contact id already exists")
        # Results are the complete contacts in input order with their new ids.
        results = []
        changed = False
        for old_id, new_id in entries:
            results.append(dict(contacts[old_id], contact_id=new_id))
            if old_id != new_id:
                changed = True
        if not changed:
            # Every rename keeps its id: report the contacts without rewriting.
            return results
        # Renames apply simultaneously against the pre-call identities, so
        # swaps and cycles land on the same final state regardless of input
        # order; each contact keeps its slot in the mapping under its new id.
        renamed = {}
        for contact_id, contact in contacts.items():
            new_id = mapping.get(contact_id)
            if new_id is None:
                renamed[contact_id] = contact
            else:
                contact["contact_id"] = new_id
                renamed[new_id] = contact
        data["contacts"] = renamed
        # Followups, opportunities (every stage), tags and reminders follow
        # their contact; everything else about those records stays as it was.
        for entry in data.get("followups", []):
            new_id = mapping.get(entry["contact_id"])
            if new_id is not None:
                entry["contact_id"] = new_id
        for opportunity in data.get("opportunities", {}).values():
            new_id = mapping.get(opportunity["contact_id"])
            if new_id is not None:
                opportunity["contact_id"] = new_id
        tag_store = data.get("tags")
        if tag_store:
            data["tags"] = {mapping.get(contact_id, contact_id): tags
                            for contact_id, tags in tag_store.items()}
        reminder_store = data.get("reminders")
        if reminder_store:
            renamed_reminders = {}
            for contact_id, reminder in reminder_store.items():
                new_id = mapping.get(contact_id)
                if new_id is None:
                    renamed_reminders[contact_id] = reminder
                else:
                    reminder["contact_id"] = new_id
                    renamed_reminders[new_id] = reminder
            data["reminders"] = renamed_reminders
        self._write(data)
        return results

    def import_contacts(self, csv_path):
        if not isinstance(csv_path, str) or not csv_path.strip():
            raise ValueError("csv_path must be a nonempty string")
        with open(csv_path, encoding="utf-8-sig", newline="") as stream:
            try:
                content = stream.read()
            except UnicodeDecodeError as error:
                raise ValueError("CSV file must be valid UTF-8") from error
        try:
            rows = csv.reader(io.StringIO(content), strict=True)
            header = next(rows, None)
        except csv.Error as error:
            raise ValueError("invalid CSV syntax") from error
        if header is None:
            raise ValueError("CSV file is empty")
        if len(header) != len(CONTACT_FIELDS) or set(header) != set(CONTACT_FIELDS) or len(set(header)) != len(header):
            raise ValueError("CSV header must contain exactly contact_id,name,email,organization in any order")

        data = self._read()
        contacts = data.setdefault("contacts", {})
        existing_emails = {c["email"] for c in contacts.values()}
        seen_ids = set()
        seen_emails = set()
        imported = []
        try:
            for row in rows:
                if not row:
                    continue
                if len(row) != len(header):
                    raise ValueError("each CSV record must have %d fields" % len(header))
                values = dict(zip(header, row))
                contact_id = text(values["contact_id"], "contact_id")
                name = text(values["name"], "name")
                organization = text(values["organization"], "organization")
                email = text(values["email"], "email").lower()
                if email.count("@") != 1 or any(c.isspace() for c in email) or not all(email.split("@")):
                    raise ValueError("invalid email")
                if contact_id in contacts or email in existing_emails:
                    raise ValueError("contact id or email already exists")
                if contact_id in seen_ids or email in seen_emails:
                    raise ValueError("duplicate contact id or email within import file")
                seen_ids.add(contact_id)
                seen_emails.add(email)
                contact = {"contact_id": contact_id, "name": name, "email": email, "organization": organization}
                contacts[contact_id] = contact
                imported.append(contact)
        except csv.Error as error:
            raise ValueError("invalid CSV syntax") from error
        if imported:
            self._write(data)
        return imported

    def preview_contact_import(self, csv_path):
        # Read-only dry run of import_contacts: same path, encoding, header,
        # quoting and field normalization rules, but nothing is registered,
        # written or created. The report lists every row-level problem so the
        # whole file can be reviewed before importing for real.
        if not isinstance(csv_path, str) or not csv_path.strip():
            raise ValueError("csv_path must be a nonempty string")
        with open(csv_path, encoding="utf-8-sig", newline="") as stream:
            try:
                content = stream.read()
            except UnicodeDecodeError as error:
                raise ValueError("CSV file must be valid UTF-8") from error
        try:
            rows = csv.reader(io.StringIO(content), strict=True)
            header = next(rows, None)
        except csv.Error as error:
            raise ValueError("invalid CSV syntax") from error
        if header is None:
            raise ValueError("CSV file is empty")
        if len(header) != len(CONTACT_FIELDS) or set(header) != set(CONTACT_FIELDS) or len(set(header)) != len(header):
            raise ValueError("CSV header must contain exactly contact_id,name,email,organization in any order")

        # Row numbers count the non-empty logical records after the header
        # from 1; quoted newlines stay inside one record and zero-field blank
        # lines never get a number.
        parsed = []
        try:
            for row in rows:
                if not row:
                    continue
                if len(row) != len(header):
                    raise ValueError("each CSV record must have %d fields" % len(header))
                parsed.append((len(parsed) + 1, dict(zip(header, row))))
        except csv.Error as error:
            raise ValueError("invalid CSV syntax") from error

        # Old data without a contacts collection reads as an empty store.
        data = self._read()
        contacts = data.get("contacts", {})
        existing_ids = set(contacts)
        existing_emails = {c["email"] for c in contacts.values()}

        # Each field normalizes independently, so a row with one bad field
        # still contributes its legal id and email to the conflict checks.
        entries = []
        for row_number, values in parsed:
            clean = {}
            invalid = set()
            for field in CONTACT_FIELDS:
                value = values[field].strip()
                if field == "email":
                    value = value.lower()
                    if (not value or value.count("@") != 1 or any(c.isspace() for c in value)
                            or not all(value.split("@"))):
                        invalid.add(field)
                        continue
                elif not value:
                    invalid.add(field)
                    continue
                clean[field] = value
            entries.append((row_number, clean, invalid))

        id_rows = {}
        email_rows = {}
        for row_number, clean, _ in entries:
            if "contact_id" in clean:
                id_rows.setdefault(clean["contact_id"], []).append(row_number)
            if "email" in clean:
                email_rows.setdefault(clean["email"], []).append(row_number)

        # A legal id or email occupied by an existing contact reports
        # "existing"; one repeated within the file reports "duplicate" on
        # every involved row, not just the later ones. Both can apply to the
        # same field of the same row and are kept as two entries.
        errors = []
        for row_number, clean, invalid in entries:
            for field in invalid:
                errors.append({"row": row_number, "field": field, "code": "invalid"})
            contact_id = clean.get("contact_id")
            if contact_id is not None:
                if contact_id in existing_ids:
                    errors.append({"row": row_number, "field": "contact_id", "code": "existing"})
                if len(id_rows[contact_id]) > 1:
                    errors.append({"row": row_number, "field": "contact_id", "code": "duplicate"})
            email = clean.get("email")
            if email is not None:
                if email in existing_emails:
                    errors.append({"row": row_number, "field": "email", "code": "existing"})
                if len(email_rows[email]) > 1:
                    errors.append({"row": row_number, "field": "email", "code": "duplicate"})
        errors.sort(key=lambda error: (error["row"], error["field"], error["code"]))

        failed_rows = {error["row"] for error in errors}
        records = [{"row": row_number,
                    "contact": {"contact_id": clean["contact_id"], "name": clean["name"],
                                "email": clean["email"], "organization": clean["organization"]}}
                   for row_number, clean, _ in entries if row_number not in failed_rows]
        return {"can_import": not errors, "records": records, "errors": errors}

    def import_followups(self, csv_path):
        if not isinstance(csv_path, str) or not csv_path.strip():
            raise ValueError("csv_path must be a nonempty string")
        with open(csv_path, encoding="utf-8-sig", newline="") as stream:
            try:
                content = stream.read()
            except UnicodeDecodeError as error:
                raise ValueError("CSV file must be valid UTF-8") from error
        try:
            rows = csv.reader(io.StringIO(content), strict=True)
            header = next(rows, None)
        except csv.Error as error:
            raise ValueError("invalid CSV syntax") from error
        if header is None:
            raise ValueError("CSV file is empty")
        if (len(header) != len(FOLLOWUP_FIELDS) or set(header) != set(FOLLOWUP_FIELDS)
                or len(set(header)) != len(header)):
            raise ValueError("CSV header must contain exactly contact_id,on,note in any order")

        records = []
        try:
            for row in rows:
                if not row:
                    continue
                if len(row) != len(header):
                    raise ValueError("each CSV record must have %d fields" % len(header))
                values = dict(zip(header, row))
                contact_id = text(values["contact_id"], "contact_id")
                on = calendar_day(values["on"], "on")
                note = text(values["note"], "note")
                records.append({"contact_id": contact_id, "on": on, "note": note})
        except csv.Error as error:
            raise ValueError("invalid CSV syntax") from error

        data = self._read()
        contacts = data.get("contacts", {})
        # The whole batch validates first, so an unknown contact rejects every row.
        for entry in records:
            if entry["contact_id"] not in contacts:
                raise ValueError("unknown contact")
        imported = []
        if records:
            store = data.setdefault("followups", [])
            for entry in records:
                # Identical rows, within the batch or against existing data, are kept verbatim.
                store.append(dict(entry))
                imported.append(dict(entry))
            self._write(data)
        return imported

    def import_opportunities(self, csv_path):
        if not isinstance(csv_path, str) or not csv_path.strip():
            raise ValueError("csv_path must be a nonempty string")
        with open(csv_path, encoding="utf-8-sig", newline="") as stream:
            try:
                content = stream.read()
            except UnicodeDecodeError as error:
                raise ValueError("CSV file must be valid UTF-8") from error
        try:
            rows = csv.reader(io.StringIO(content), strict=True)
            header = next(rows, None)
        except csv.Error as error:
            raise ValueError("invalid CSV syntax") from error
        if header is None:
            raise ValueError("CSV file is empty")
        if (len(header) != len(OPPORTUNITY_FIELDS) or set(header) != set(OPPORTUNITY_FIELDS)
                or len(set(header)) != len(header)):
            raise ValueError(
                "CSV header must contain exactly opportunity_id,contact_id,title,stage in any order")

        records = []
        try:
            for row in rows:
                if not row:
                    continue
                if len(row) != len(header):
                    raise ValueError("each CSV record must have %d fields" % len(header))
                values = dict(zip(header, row))
                opportunity_id = text(values["opportunity_id"], "opportunity_id")
                contact_id = text(values["contact_id"], "contact_id")
                title = text(values["title"], "title")
                stage = values["stage"].strip()
                if stage not in STAGES:
                    raise ValueError("invalid stage")
                records.append({"opportunity_id": opportunity_id, "contact_id": contact_id,
                                "title": title, "stage": stage})
        except csv.Error as error:
            raise ValueError("invalid CSV syntax") from error

        data = self._read()
        contacts = data.get("contacts", {})
        opportunities = data.get("opportunities", {})
        # The whole batch validates before any write: unknown contacts and
        # duplicate ids (existing or within the batch, even identical rows) reject it all.
        seen = set()
        for entry in records:
            if entry["contact_id"] not in contacts:
                raise ValueError("unknown contact")
            if entry["opportunity_id"] in opportunities or entry["opportunity_id"] in seen:
                raise ValueError("opportunity id already exists")
            seen.add(entry["opportunity_id"])
        imported = []
        if records:
            store = data.setdefault("opportunities", {})
            for entry in records:
                opportunity = dict(entry)
                store[entry["opportunity_id"]] = opportunity
                imported.append(dict(opportunity))
            self._write(data)
        return imported

    def import_contact_tags(self, csv_path):
        # Append-only tag supplement for already registered contacts: it never
        # removes tags, creates contacts or lets a blank tag clear data. The
        # whole file validates before any write, like the other CSV imports.
        if not isinstance(csv_path, str) or not csv_path.strip():
            raise ValueError("csv_path must be a nonempty string")
        with open(csv_path, encoding="utf-8-sig", newline="") as stream:
            try:
                content = stream.read()
            except UnicodeDecodeError as error:
                raise ValueError("CSV file must be valid UTF-8") from error
        try:
            rows = csv.reader(io.StringIO(content), strict=True)
            header = next(rows, None)
        except csv.Error as error:
            raise ValueError("invalid CSV syntax") from error
        if header is None:
            raise ValueError("CSV file is empty")
        if (len(header) != len(TAG_IMPORT_FIELDS) or set(header) != set(TAG_IMPORT_FIELDS)
                or len(set(header)) != len(header)):
            raise ValueError("CSV header must contain exactly contact_id,tag in any order")

        entries = []
        try:
            for row in rows:
                if not row:
                    # Only a genuine zero-field blank line is ignored; a pair of
                    # empty fields is a record with a blank id and blank tag.
                    continue
                if len(row) != len(header):
                    raise ValueError("each CSV record must have %d fields" % len(header))
                values = dict(zip(header, row))
                # Ids trim but stay case-sensitive; tags reuse set-tags exactly:
                # trim, casefold, keep inner whitespace, and reject blank ones.
                contact_id = text(values["contact_id"], "contact_id")
                tag = values["tag"].strip().casefold()
                if not tag:
                    raise ValueError("tags must be nonempty strings")
                entries.append((contact_id, tag))
        except csv.Error as error:
            raise ValueError("invalid CSV syntax") from error

        data = self._read()
        contacts = data.get("contacts", {})
        # Every contact is checked up front, so an unknown id in a later row
        # rejects tags parsed from earlier rows too.
        for contact_id, _ in entries:
            if contact_id not in contacts:
                raise ValueError("unknown contact")
        store = data.get("tags", {})
        order = []
        unions = {}
        changed = False
        for contact_id, tag in entries:
            if contact_id not in unions:
                # Result order follows the normalized id's first file appearance.
                order.append(contact_id)
                unions[contact_id] = set(store.get(contact_id, []))
            if tag not in unions[contact_id]:
                # Only a tag absent both from the stored set and from earlier
                # file rows counts as a change; identical rows duplicate freely.
                unions[contact_id].add(tag)
                changed = True
        results = [{"contact_id": contact_id, "tags": sorted(unions[contact_id])}
                   for contact_id in order]
        if changed:
            for contact_id, tags in unions.items():
                store[contact_id] = sorted(tags)
            data["tags"] = store
            self._write(data)
        return results

    def follow_up(self, contact_id, on, note):
        note = text(note, "note")
        on = date.fromisoformat(on).isoformat()
        data = self._read()
        if contact_id not in data.get("contacts", {}):
            raise ValueError("unknown contact")
        entry = {"contact_id": contact_id, "on": on, "note": note}
        data.setdefault("followups", []).append(entry)
        self._write(data)
        return entry

    def set_reminder(self, contact_id, due_on, note, repeat_monthly=False):
        contact_id = text(contact_id, "contact_id")
        note = text(note, "note")
        due_on = calendar_day(due_on, "due_on")
        # Only a real boolean toggles repetition; ints, strings and null reject.
        if type(repeat_monthly) is not bool:
            raise ValueError("repeat_monthly must be a boolean")
        data = self._read()
        if contact_id not in data.get("contacts", {}):
            raise ValueError("unknown contact")
        # Each contact keeps at most one reminder; setting again replaces the whole
        # entry, so an omitted or false repeat_monthly also drops any previous rule.
        reminder = {"contact_id": contact_id, "due_on": due_on, "note": note}
        if repeat_monthly:
            # The first due date's day of month anchors every later renewal.
            reminder["repeat_monthly"] = True
            reminder["anchor_day"] = int(due_on[8:10])
        data.setdefault("reminders", {})[contact_id] = reminder
        self._write(data)
        return dict(reminder)

    def clear_reminder(self, contact_id):
        contact_id = text(contact_id, "contact_id")
        data = self._read()
        if contact_id not in data.get("contacts", {}):
            raise ValueError("unknown contact")
        store = data.get("reminders", {})
        if contact_id not in store:
            # Nothing to clear: report False without touching the file.
            return False
        del store[contact_id]
        if not store:
            data.pop("reminders", None)
        self._write(data)
        return True

    def complete_reminder(self, contact_id, on, note, next_reminder=_UNSET):
        contact_id = text(contact_id, "contact_id")
        note = text(note, "note")
        on = calendar_day(on, "on")
        pending = None
        if next_reminder is not _UNSET and next_reminder is not None:
            if not isinstance(next_reminder, dict) or set(next_reminder) != {"due_on", "note"}:
                raise ValueError("next_reminder must be an object with exactly due_on and note")
            due_on = calendar_day(next_reminder["due_on"], "due_on")
            if due_on <= on:
                raise ValueError("next reminder due_on must be later than the completion date")
            pending = {"contact_id": contact_id, "due_on": due_on,
                       "note": text(next_reminder["note"], "note")}
        # Everything validates before this point, so rejected calls never touch the file.
        data = self._read()
        if contact_id not in data.get("contacts", {}):
            raise ValueError("unknown contact")
        store = data.get("reminders", {})
        current = store.get(contact_id)
        if current is None:
            raise ValueError("no current reminder")
        if next_reminder is _UNSET and _is_repeating(current):
            # An omitted next_reminder renews a monthly reminder from its anchor
            # instead of clearing it; an explicit null still terminates it.
            pending = _renewed_reminder(current, on)
        # Followup append and reminder clear/replace commit in a single write.
        entry = {"contact_id": contact_id, "on": on, "note": note}
        data.setdefault("followups", []).append(entry)
        if pending is None:
            del store[contact_id]
            if not store:
                data.pop("reminders", None)
        else:
            store[contact_id] = pending
        self._write(data)
        return {"followup": dict(entry),
                "reminder": dict(pending) if pending is not None else None}

    def complete_reminders(self, completions):
        # The whole batch validates before any followup is appended or reminder
        # cleared/replaced, so a rejected item never leaves half the batch applied;
        # every append and reminder change commits in a single write.
        if not isinstance(completions, list):
            raise ValueError("completions must be a list")
        if not completions:
            # An empty batch succeeds with an empty result and never touches storage.
            return []
        REQUIRED_KEYS = {"contact_id", "expected_due_on", "on", "note"}
        COMPLETION_KEYS = REQUIRED_KEYS | {"next_reminder"}
        entries = []
        seen = set()
        for item in completions:
            if not isinstance(item, dict) or not REQUIRED_KEYS <= set(item) <= COMPLETION_KEYS:
                raise ValueError(
                    "each completion must be an object with contact_id, expected_due_on, "
                    "on, note and an optional next_reminder")
            contact_id = text(item["contact_id"], "contact_id")
            note = text(item["note"], "note")
            on = calendar_day(item["on"], "on")
            expected_due_on = calendar_day(item["expected_due_on"], "expected_due_on")
            # An omitted next_reminder is resolved against the stored reminder
            # after the read; an explicit null terminates any repetition.
            pending = _UNSET
            if "next_reminder" in item:
                next_reminder = item["next_reminder"]
                if next_reminder is None:
                    pending = None
                else:
                    if not isinstance(next_reminder, dict) or set(next_reminder) != {"due_on", "note"}:
                        raise ValueError(
                            "next_reminder must be an object with exactly due_on and note")
                    due_on = calendar_day(next_reminder["due_on"], "due_on")
                    if due_on <= on:
                        raise ValueError(
                            "next reminder due_on must be later than the completion date")
                    pending = {"contact_id": contact_id, "due_on": due_on,
                               "note": text(next_reminder["note"], "note")}
            # Normalized ids are case-sensitive; a repeated contact id (even an
            # identical item) rejects the whole batch.
            if contact_id in seen:
                raise ValueError("duplicate contact id in completions")
            seen.add(contact_id)
            entries.append((contact_id, expected_due_on, on, note, pending))
        data = self._read()
        contacts = data.get("contacts", {})
        store = data.get("reminders", {})
        planned = []
        for contact_id, expected_due_on, on, note, pending in entries:
            if contact_id not in contacts:
                raise ValueError("unknown contact")
            current = store.get(contact_id)
            if current is None:
                raise ValueError("no current reminder")
            # The note never participates in the check: only the current due date
            # must equal the expected one supplied with the completion.
            if current["due_on"] != expected_due_on:
                raise ValueError("expected_due_on does not match the current reminder due_on")
            if pending is _UNSET:
                # Omitted next_reminder: a monthly reminder renews from its
                # anchor; a one-time reminder simply clears.
                pending = _renewed_reminder(current, on) if _is_repeating(current) else None
            entry = {"contact_id": contact_id, "on": on, "note": note}
            planned.append((contact_id, entry, pending))
        # Everything validated; results follow input order and complete-reminder's shape.
        results = [{"followup": dict(entry),
                    "reminder": dict(pending) if pending is not None else None}
                   for _, entry, pending in planned]
        followups = data.setdefault("followups", [])
        for contact_id, entry, pending in planned:
            followups.append(entry)
            if pending is None:
                del store[contact_id]
            else:
                store[contact_id] = pending
        if not store:
            data.pop("reminders", None)
        self._write(data)
        return results

    def postpone_reminders(self, updates):
        # Move reminders' due dates only: no followup is appended and no
        # reminder is rebuilt. The whole batch validates against the pre-call
        # reminders before any due date changes, so a rejected item never
        # leaves part of the batch postponed; every change commits in one write.
        if not isinstance(updates, list):
            raise ValueError("updates must be a list")
        if not updates:
            # An empty batch succeeds with an empty result and never touches storage.
            return []
        update_keys = {"contact_id", "expected_due_on", "due_on"}
        entries = []
        seen = set()
        for item in updates:
            if not isinstance(item, dict) or set(item) != update_keys:
                raise ValueError(
                    "each update must be an object with exactly contact_id, "
                    "expected_due_on and due_on")
            contact_id = text(item["contact_id"], "contact_id")
            # Both dates reuse the real-calendar rule (trimmed YYYY-MM-DD, past,
            # future, cross-year and legal leap days allowed, no system clock).
            expected_due_on = calendar_day(item["expected_due_on"], "expected_due_on")
            due_on = calendar_day(item["due_on"], "due_on")
            # The new due date may stay the same but must not move backwards.
            if due_on < expected_due_on:
                raise ValueError("due_on must not be earlier than expected_due_on")
            # Normalized ids are case-sensitive; a repeated contact id (even an
            # identical item) rejects the whole batch.
            if contact_id in seen:
                raise ValueError("duplicate contact id in updates")
            seen.add(contact_id)
            entries.append((contact_id, expected_due_on, due_on))
        data = self._read()
        contacts = data.get("contacts", {})
        store = data.get("reminders", {})
        planned = []
        for contact_id, expected_due_on, due_on in entries:
            if contact_id not in contacts:
                raise ValueError("unknown contact")
            current = store.get(contact_id)
            if current is None:
                raise ValueError("no current reminder")
            # Every check uses the pre-call state: the current due date must
            # equal the expected one, even when the same contact appears only
            # once in the batch.
            if current["due_on"] != expected_due_on:
                raise ValueError("expected_due_on does not match the current reminder due_on")
            updated = dict(current)
            updated["due_on"] = due_on
            planned.append((current, updated))
        # Results are the complete reminders in input order; an unchanged item
        # reports its original reminder. When every date already matches, report
        # the reminders without rewriting the file.
        if all(current == updated for current, updated in planned):
            return [dict(updated) for _, updated in planned]
        # Only due_on changes: the note and any existing repeat_monthly /
        # anchor_day fields carry over verbatim, and one-time reminders gain no
        # repetition fields.
        for current, updated in planned:
            current["due_on"] = updated["due_on"]
        self._write(data)
        return [dict(updated) for _, updated in planned]

    def due_reminders(self, as_of):
        as_of = calendar_day(as_of, "as_of")
        data = self._read()
        due = [dict(reminder) for reminder in data.get("reminders", {}).values()
               if reminder["due_on"] <= as_of]
        # Ascending due date; the same day orders by contact id code point.
        return sorted(due, key=lambda reminder: (reminder["due_on"], reminder["contact_id"]))

    def set_tags(self, contact_id, tags):
        contact_id = text(contact_id, "contact_id")
        tags = normalize_tags(tags)
        data = self._read()
        if contact_id not in data.get("contacts", {}):
            raise ValueError("unknown contact")
        store = data.setdefault("tags", {})
        if tags:
            store[contact_id] = tags
        else:
            store.pop(contact_id, None)
        if not store:
            data.pop("tags", None)
        self._write(data)
        return list(tags)

    def get_tags(self, contact_id):
        contact_id = text(contact_id, "contact_id")
        data = self._read()
        if contact_id not in data.get("contacts", {}):
            raise ValueError("unknown contact")
        return list(data.get("tags", {}).get(contact_id, []))

    def rename_tags(self, renames):
        # Rename tags across every contact in one batch. The whole batch
        # validates against the pre-call tag sets before any tag changes, so a
        # rejected batch never touches storage; every rename commits in a
        # single write.
        if not isinstance(renames, list):
            raise ValueError("renames must be a list")
        if not renames:
            # An empty batch succeeds with an empty result and never touches storage.
            return []
        entries = []
        seen = set()
        for item in renames:
            if not isinstance(item, dict) or set(item) != {"old_tag", "new_tag"}:
                raise ValueError("each rename must be an object with exactly old_tag and new_tag")
            old_tag = normalize_tag(item["old_tag"])
            new_tag = normalize_tag(item["new_tag"])
            # Normalized source names are casefolded; a repeated source (even an
            # identical item) rejects the whole batch. Targets repeat freely, so
            # several sources may merge into one name.
            if old_tag in seen:
                raise ValueError("duplicate old tag in renames")
            seen.add(old_tag)
            entries.append((old_tag, new_tag))
        data = self._read()
        contacts = data.get("contacts", {})
        tag_store = data.get("tags", {})
        # Every source tag must be used by at least one existing contact before
        # the call; a missing tags collection (old data) reads as the empty set.
        in_use = {tag for contact_id, tags in tag_store.items()
                  if contact_id in contacts for tag in tags}
        for old_tag, _ in entries:
            if old_tag not in in_use:
                raise ValueError("unknown tag")
        mapping = dict(entries)
        # Renames apply simultaneously against the pre-call sets: each original
        # tag is replaced at most once and targets are never re-renamed, so
        # identity renames, swaps and cycles land on the same final state
        # regardless of input order.
        changed = []
        for contact_id in sorted(tag_store):
            if contact_id not in contacts:
                continue
            tags = tag_store[contact_id]
            renamed = sorted({mapping.get(tag, tag) for tag in tags})
            if set(renamed) != set(tags):
                changed.append((contact_id, renamed))
        if not changed:
            # No contact's set actually changes: report [] without rewriting.
            return []
        for contact_id, renamed in changed:
            tag_store[contact_id] = renamed
        self._write(data)
        # Only contacts whose set changed are reported, ids and tags both in
        # ascending code point order.
        return [{"contact_id": contact_id, "tags": tags} for contact_id, tags in changed]

    def add_opportunity(self, opportunity_id, contact_id, title):
        opportunity_id = text(opportunity_id, "opportunity_id")
        title = text(title, "title")
        contact_id = text(contact_id, "contact_id")
        data = self._read()
        if contact_id not in data.get("contacts", {}):
            raise ValueError("unknown contact")
        opportunities = data.setdefault("opportunities", {})
        if opportunity_id in opportunities:
            raise ValueError("opportunity id already exists")
        opportunity = {"opportunity_id": opportunity_id, "contact_id": contact_id, "title": title, "stage": "new"}
        opportunities[opportunity_id] = opportunity
        self._write(data)
        return {"opportunity_id": opportunity_id, "contact_id": contact_id, "title": title, "stage": "new"}

    def set_stage(self, opportunity_id, stage, on=None):
        opportunity_id = text(opportunity_id, "opportunity_id")
        stage = text(stage, "stage")
        if stage not in STAGES:
            raise ValueError("invalid stage")
        # An omitted or None date is stored as null; a provided date must be a
        # trimmed real YYYY-MM-DD string (past, future and leap days allowed).
        on = None if on is None else calendar_day(on, "on")
        data = self._read()
        opportunity = data.get("opportunities", {}).get(opportunity_id)
        if opportunity is None:
            raise ValueError("unknown opportunity")
        current = opportunity["stage"]
        if stage != current and stage not in STAGE_TRANSITIONS.get(current, ()):
            raise ValueError("invalid stage transition")
        # Every provided date is validated, even on a same-stage no-op: it must
        # not precede the latest non-null date already recorded for this deal.
        # Null records never move that lower bound.
        history = data.get("stage_history", {}).get(opportunity_id, [])
        if on is not None:
            dated = [entry["on"] for entry in history if entry["on"] is not None]
            if dated and on < dated[-1]:
                raise ValueError("on must not be earlier than the latest recorded stage date")
        if stage != current:
            opportunity["stage"] = stage
            # Stage change and history append commit in a single write; the
            # history lives outside the opportunity object itself.
            data.setdefault("stage_history", {}).setdefault(opportunity_id, []).append(
                {"from_stage": current, "to_stage": stage, "on": on})
            self._write(data)
        return dict(opportunity)

    def set_stages(self, updates):
        # The whole batch validates against each deal's pre-call stage before any
        # stage or history changes, so a rejected item never leaves half the batch
        # applied; stage changes and history appends commit in a single write.
        if not isinstance(updates, list):
            raise ValueError("updates must be a list")
        if not updates:
            # An empty batch succeeds with an empty result and never touches storage.
            return []
        allowed_keys = {"opportunity_id", "stage", "on"}
        entries = []
        seen = set()
        for item in updates:
            if (not isinstance(item, dict)
                    or not {"opportunity_id", "stage"} <= set(item)
                    or not set(item) <= allowed_keys):
                raise ValueError(
                    "each update must be an object with opportunity_id, stage and an optional on")
            opportunity_id = text(item["opportunity_id"], "opportunity_id")
            stage = text(item["stage"], "stage")
            if stage not in STAGES:
                raise ValueError("invalid stage")
            # An omitted or None date is stored as null; a provided date must be a
            # trimmed real YYYY-MM-DD string (past, future and leap days allowed).
            on = item.get("on")
            on = None if on is None else calendar_day(on, "on")
            # Normalized ids are case-sensitive; a repeated opportunity id (even an
            # identical item) rejects the whole batch.
            if opportunity_id in seen:
                raise ValueError("duplicate opportunity id in updates")
            seen.add(opportunity_id)
            entries.append((opportunity_id, stage, on))
        data = self._read()
        opportunities = data.get("opportunities", {})
        history_store = data.get("stage_history", {})
        planned = []
        changed = False
        for opportunity_id, stage, on in entries:
            opportunity = opportunities.get(opportunity_id)
            if opportunity is None:
                raise ValueError("unknown opportunity")
            current = opportunity["stage"]
            if stage != current and stage not in STAGE_TRANSITIONS.get(current, ()):
                raise ValueError("invalid stage transition")
            # Every provided date is validated, even on a same-stage no-op: it must
            # not precede the latest non-null date already recorded for this deal.
            # Null records never move that lower bound. Each deal appears once, so
            # the pre-call history is the only history its date is checked against.
            if on is not None:
                dated = [entry["on"] for entry in history_store.get(opportunity_id, [])
                         if entry["on"] is not None]
                if dated and on < dated[-1]:
                    raise ValueError("on must not be earlier than the latest recorded stage date")
            if stage != current:
                changed = True
            planned.append((opportunity_id, opportunity, current, stage, on))
        # Results are the complete opportunities in input order, unchanged on a no-op batch.
        results = []
        if not changed:
            # Every item repeated its current stage: report the originals
            # without rewriting the file.
            for _, opportunity, _, _, _ in planned:
                results.append(dict(opportunity))
            return results
        for opportunity_id, opportunity, current, stage, on in planned:
            if stage != current:
                opportunity["stage"] = stage
                # The history lives outside the opportunity object itself;
                # deals without a history collection start from an empty one.
                history_store.setdefault(opportunity_id, []).append(
                    {"from_stage": current, "to_stage": stage, "on": on})
            results.append(dict(opportunity))
        data.setdefault("stage_history", history_store)
        self._write(data)
        return results

    def stage_history(self, opportunity_id):
        opportunity_id = text(opportunity_id, "opportunity_id")
        data = self._read()
        if opportunity_id not in data.get("opportunities", {}):
            raise ValueError("unknown opportunity")
        # Records stay in successful-change order, never re-sorted by date;
        # deals without any recorded change read as an empty history.
        return [dict(entry) for entry in data.get("stage_history", {}).get(opportunity_id, [])]

    def correct_stage_dates(self, corrections):
        # Back-fill or fix the business dates of already saved stage-history
        # records. The whole batch validates and commits together; a rejected
        # batch never touches the file.
        if not isinstance(corrections, list):
            raise ValueError("corrections must be a list")
        if not corrections:
            # An empty batch succeeds with an empty result and never touches storage.
            return []
        correction_keys = {"opportunity_id", "index", "on"}
        entries = []
        seen = set()
        for item in corrections:
            if not isinstance(item, dict) or set(item) != correction_keys:
                raise ValueError(
                    "each correction must be an object with exactly opportunity_id, index and on")
            opportunity_id = text(item["opportunity_id"], "opportunity_id")
            # type(...) is int rejects bools, which are ints in Python but never an index.
            index = item["index"]
            if type(index) is not int or index < 0:
                raise ValueError("index must be a nonnegative integer")
            # Dates reuse the real-calendar rule (trimmed YYYY-MM-DD, past,
            # future and leap days allowed, null rejected, no system clock).
            on = calendar_day(item["on"], "on")
            # Normalized ids are case-sensitive; the same position of one deal
            # may appear only once, even when both items are identical.
            if (opportunity_id, index) in seen:
                raise ValueError("duplicate correction for the same opportunity and index")
            seen.add((opportunity_id, index))
            entries.append((opportunity_id, index, on))
        data = self._read()
        opportunities = data.get("opportunities", {})
        history_store = data.get("stage_history", {})
        involved = {}
        for opportunity_id, index, _ in entries:
            if opportunity_id not in opportunities:
                raise ValueError("unknown opportunity")
            # Deals without a history collection (including old data) read as empty.
            history = history_store.get(opportunity_id, [])
            if index >= len(history):
                raise ValueError("index out of range for stage history")
            involved[opportunity_id] = history
        # Apply on copies so final monotonicity is judged on the post-correction
        # history while storage stays untouched until everything validates.
        corrected = {opportunity_id: [dict(entry) for entry in history]
                     for opportunity_id, history in involved.items()}
        for opportunity_id, index, on in entries:
            corrected[opportunity_id][index]["on"] = on
        for history in corrected.values():
            # Non-null dates in save order must not go backwards; same day is
            # allowed and untouched null records never participate.
            previous = None
            for entry in history:
                if entry["on"] is not None:
                    if previous is not None and entry["on"] < previous:
                        raise ValueError("stage dates must not go backwards")
                    previous = entry["on"]
        # Results are the corrected records in input order, shaped like stage-history.
        results = [dict(corrected[opportunity_id][index])
                   for opportunity_id, index, _ in entries]
        if all(corrected[opportunity_id] == involved[opportunity_id]
               for opportunity_id in involved):
            # Every normalized date already matched the stored one: report the
            # records without rewriting the file.
            return results
        store = data.setdefault("stage_history", {})
        for opportunity_id, history in corrected.items():
            store[opportunity_id] = history
        self._write(data)
        return results

    def reopen_opportunities(self, reopens):
        # Reopen a batch of closed deals back to qualified. The whole batch
        # validates against each deal's pre-call stage before any stage or
        # history changes, so a rejected item never leaves half the batch
        # applied; stage changes and history appends commit in a single write.
        if not isinstance(reopens, list):
            raise ValueError("reopens must be a list")
        if not reopens:
            # An empty batch succeeds with an empty result and never touches storage.
            return []
        reopen_keys = {"opportunity_id", "expected_stage", "on"}
        entries = []
        seen = set()
        for item in reopens:
            if not isinstance(item, dict) or set(item) != reopen_keys:
                raise ValueError(
                    "each reopen must be an object with exactly opportunity_id, "
                    "expected_stage and on")
            opportunity_id = text(item["opportunity_id"], "opportunity_id")
            # Only the two terminal stages can be expected, case preserved.
            expected_stage = text(item["expected_stage"], "expected_stage")
            if expected_stage not in ("won", "lost"):
                raise ValueError("expected_stage must be won or lost")
            # The reopen date is required: a trimmed real YYYY-MM-DD string
            # (past, future and leap days allowed, no system clock).
            on = calendar_day(item["on"], "on")
            # Normalized ids are case-sensitive; a repeated opportunity id (even
            # an identical item) rejects the whole batch.
            if opportunity_id in seen:
                raise ValueError("duplicate opportunity id in reopens")
            seen.add(opportunity_id)
            entries.append((opportunity_id, expected_stage, on))
        data = self._read()
        opportunities = data.get("opportunities", {})
        history_store = data.get("stage_history", {})
        planned = []
        for opportunity_id, expected_stage, on in entries:
            opportunity = opportunities.get(opportunity_id)
            if opportunity is None:
                raise ValueError("unknown opportunity")
            # Only a closed deal reopens, and the claimed stage must equal the
            # actual current one; an already reopened (qualified) deal rejects
            # until it is closed again.
            if opportunity["stage"] != expected_stage:
                raise ValueError("expected_stage does not match the current stage")
            # The date must not precede the latest non-null date already
            # recorded for this deal; same day is allowed and null records
            # never move that lower bound. Each deal appears once, so the
            # pre-call history is the only history its date is checked against.
            dated = [entry["on"] for entry in history_store.get(opportunity_id, [])
                     if entry["on"] is not None]
            if dated and on < dated[-1]:
                raise ValueError("on must not be earlier than the latest recorded stage date")
            planned.append((opportunity_id, opportunity, expected_stage, on))
        # Results are the complete opportunities in input order; ids, titles,
        # ownership and amounts stay as they were, and a deal never priced
        # keeps no amount field.
        results = []
        for opportunity_id, opportunity, expected_stage, on in planned:
            opportunity["stage"] = "qualified"
            # The history lives outside the opportunity object itself; deals
            # without a history collection (old data included) start recording
            # from the closed stage, with no back-filled earlier records.
            history_store.setdefault(opportunity_id, []).append(
                {"from_stage": expected_stage, "to_stage": "qualified", "on": on})
            results.append(dict(opportunity))
        data.setdefault("stage_history", history_store)
        self._write(data)
        return results

    def set_opportunity_amount(self, opportunity_id, amount):
        opportunity_id = text(opportunity_id, "opportunity_id")
        amount = amount_string(amount, "amount")
        data = self._read()
        opportunity = data.get("opportunities", {}).get(opportunity_id)
        if opportunity is None:
            raise ValueError("unknown opportunity")
        # Terminal stages accept amounts too; an unset amount reads as 0.00, so
        # setting zero on a never-priced opportunity is a no-op like any equal value.
        current = opportunity.get("amount", "0.00")
        if current != amount:
            opportunity["amount"] = amount
            self._write(data)
        return {"opportunity_id": opportunity_id, "amount": amount}

    def set_close_dates(self, updates):
        # Maintain each deal's expected close date as an optional field on the
        # opportunity object itself. The whole batch validates against the
        # pre-call opportunities before any field is added or removed, so a
        # rejected item never leaves half the batch applied; every change
        # commits in a single write.
        if not isinstance(updates, list):
            raise ValueError("updates must be a list")
        if not updates:
            # An empty batch succeeds with an empty result and never touches storage.
            return []
        update_keys = {"opportunity_id", "expected_close_on"}
        entries = []
        seen = set()
        for item in updates:
            if not isinstance(item, dict) or set(item) != update_keys:
                raise ValueError(
                    "each update must be an object with exactly opportunity_id and expected_close_on")
            opportunity_id = text(item["opportunity_id"], "opportunity_id")
            # A null value clears; a given value must be a trimmed real
            # YYYY-MM-DD string (past, future and leap days allowed, no system
            # clock). Dates normalize exactly like every other calendar day.
            raw_date = item["expected_close_on"]
            expected_close_on = None if raw_date is None else calendar_day(raw_date, "expected_close_on")
            # Normalized ids are case-sensitive; a repeated opportunity id (even
            # an identical item) rejects the whole batch.
            if opportunity_id in seen:
                raise ValueError("duplicate opportunity id in updates")
            seen.add(opportunity_id)
            entries.append((opportunity_id, expected_close_on))
        data = self._read()
        opportunities = data.get("opportunities", {})
        planned = []
        for opportunity_id, expected_close_on in entries:
            opportunity = opportunities.get(opportunity_id)
            if opportunity is None:
                raise ValueError("unknown opportunity")
            # Reported results are complete opportunities in input order,
            # carrying the maintained date or omitting the field once cleared.
            updated = dict(opportunity)
            if expected_close_on is None:
                updated.pop("expected_close_on", None)
            else:
                updated["expected_close_on"] = expected_close_on
            planned.append((opportunity, updated))
        if all(opportunity == updated for opportunity, updated in planned):
            # Every normalized date already matched: report the opportunities
            # without rewriting the file or creating the data directory.
            return [updated for _, updated in planned]
        for opportunity, updated in planned:
            if "expected_close_on" in updated:
                opportunity["expected_close_on"] = updated["expected_close_on"]
            else:
                opportunity.pop("expected_close_on", None)
        self._write(data)
        return [dict(opportunity) for opportunity, _ in planned]

    def find_opportunities(self, contact_id=None, stage=None):
        if contact_id is not None:
            contact_id = text(contact_id, "contact_id")
        if stage is not None:
            stage = text(stage, "stage")
            if stage not in STAGES:
                raise ValueError("invalid stage")
        data = self._read()
        contacts = data.get("contacts", {})
        if contact_id is not None and contact_id not in contacts:
            raise ValueError("unknown contact")

        def matches(opportunity):
            if contact_id is not None and opportunity["contact_id"] != contact_id:
                return False
            if stage is not None and opportunity["stage"] != stage:
                return False
            return True

        return [dict(opportunity) for opportunity in sorted(
            (o for o in data.get("opportunities", {}).values() if matches(o)),
            key=lambda o: o["opportunity_id"])]

    def transfer_opportunities(self, transfers):
        # The whole batch validates before any ownership changes, so a rejected
        # transfer never leaves an opportunity on a half-updated contact.
        if not isinstance(transfers, list):
            raise ValueError("transfers must be a list")
        if not transfers:
            # An empty batch succeeds with an empty result and never touches storage.
            return []
